class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        graph = [[] for _ in range(numCourses)]
        indeg = [0] * numCourses
        for cur, pre in prerequisites:
            graph[pre].append(cur)
            indeg[cur] += 1
        queue = [i for i in range(numCourses) if indeg[i] == 0]
        head = 0
        order = []
        while head < len(queue):
            node = queue[head]
            head += 1
            order.append(node)
            for nxt in graph[node]:
                indeg[nxt] -= 1
                if indeg[nxt] == 0:
                    queue.append(nxt)
        return order if len(order) == numCourses else []

class Solution:
    def pacificAtlantic(self, heights: List[List[int]]) -> List[List[int]]:
        m, n = len(heights), len(heights[0])

        def flow(starts):
            seen = [[False] * n for _ in range(m)]
            stack = []
            for x, y in starts:
                if not seen[x][y]:
                    seen[x][y] = True
                    stack.append((x, y))
            while stack:
                x, y = stack.pop()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n and not seen[nx][ny] \
                            and heights[nx][ny] >= heights[x][y]:
                        seen[nx][ny] = True
                        stack.append((nx, ny))
            return seen

        pac = flow([(0, j) for j in range(n)] + [(i, 0) for i in range(m)])
        atl = flow([(m - 1, j) for j in range(n)] + [(i, n - 1) for i in range(m)])
        res = []
        for i in range(m):
            for j in range(n):
                if pac[i][j] and atl[i][j]:
                    res.append([i, j])
        return res

