    def findRedundantDirectedConnection(self, edges: List[List[int]]) -> List[int]:
        n = len(edges)
        indeg = [0] * (n + 1)
        for u, v in edges:
            indeg[v] += 1
        dup = [i for i in range(n) if indeg[edges[i][1]] == 2]
