class Solution:
    def networkDelayTime(self, times: List[List[int]], n: int, k: int) -> int:
        INF = float('inf')
        graph = [[] for _ in range(n + 1)]
        for u, v, w in times:
            graph[u].append((v, w))
        dist = [INF] * (n + 1)
        dist[k] = 0
        done = [False] * (n + 1)
        for _ in range(n):
            node = 0
            for i in range(1, n + 1):
                if not done[i] and (node == 0 or dist[i] < dist[node]):
                    node = i
            if node == 0 or dist[node] == INF:
                break
            done[node] = True
            for v, w in graph[node]:
                if dist[node] + w < dist[v]:
                    dist[v] = dist[node] + w
        ans = max(dist[1:])
        return -1 if ans == INF else ans

