class Solution:
    def findCheapestPrice(self, n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:
        INF = 10 ** 9
        dist = [INF] * n
        dist[src] = 0
        for _ in range(k + 1):
            prev = dist[:]
            for u, v, p in flights:
                if prev[u] + p < dist[v]:
                    dist[v] = prev[u] + p
