    def largestIsland(self, grid: List[List[int]]) -> int:
        n = len(grid)
        label = [[0] * n for _ in range(n)]
        area = [0]
        cur = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j] != 1 or label[i][j] != 0:
                    continue
                cur += 1
                label[i][j] = cur
