                        if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 1 \
                                and label[nx][ny] == 0:
                            label[nx][ny] = cur
                            stack.append((nx, ny))
                area.append(size)
        best = max(area)
        for i in range(n):
            for j in range(n):
