    def canVisitAllRooms(self, rooms: List[List[int]]) -> bool:
        n = len(rooms)
        seen = [False] * n
        seen[0] = True
        stack = [0]
        count = 1
        while stack:
            node = stack.pop()
            for key in rooms[node]:
                if not seen[key]:
                    seen[key] = True
                    count += 1
                    stack.append(key)
        return count == n

